/**
 * Lines of output that follow the newest line (`design/components/log-view.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/log-view.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  claimSlot,
  createCell,
  elementRef,
  followEnd,
  jumpToEnd,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/log-view.module.css'
import Button from '../controls/Button'

export interface LogLine {
  /** Unique in the log and the same on every render: the line's key. */
  id: string
  /** The line as it was written. Whitespace is content. */
  text: string
  /** How serious the line is, drawn as a marker and read as a word. */
  level?: 'info' | 'warning' | 'error'
  /** When the line was written, already formatted by the application. */
  time?: string
  /** What wrote the line, such as a service, a process or a build step. */
  source?: string
}

export interface LogViewMessages {
  /** The label of the button that returns the reader to the newest line. */
  jumpToLatest: string
  /** Read before a line whose level is `info`. */
  info: string
  /** Read before a line whose level is `warning`. */
  warning: string
  /** Read before a line whose level is `error`. */
  error: string
}

export interface LogViewProps {
  /**
   * The log's accessible name, such as "Build output" in the app's language.
   */
  label: string
  /**
   * The lines to show, oldest first. The application trims the old ones.
   */
  lines: LogLine[]
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: LogViewMessages
  /**
   * Whether more lines are coming, which draws a caret after the last line and sets `aria-busy`.
   */
  streaming?: boolean
  /**
   * Whether a long line wraps, which is the default. `false` keeps each line on one row and
   * scrolls the log sideways, for output whose columns line up.
   */
  wrap?: boolean
}

/** Lines of output that follow the newest line. */
export default function LogView(given: LogViewProps): JSX.Element {
  const props = mergeProps(
    {
      streaming: false,
      wrap: true,
      messages: (() => ({
        jumpToLatest: 'Jump to latest',
        info: 'info',
        warning: 'warning',
        error: 'error',
      }))(),
    } as Defaults<LogViewProps, 'streaming' | 'wrap' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const detached = createCell(false)
    const overflowing = createCell(false)
    const list = elementRef<HTMLElement>()
    const viewport = elementRef<HTMLElement>()
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = followEnd(viewport.value, list.value, (state) => {
        detached.value = state.detached
        overflowing.value = state.overflowing
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        class={styles.root}
        data-state={detached.value ? 'detached' : undefined}
        data-streaming={props.streaming ? '' : undefined}
        data-wrap={props.wrap ? '' : undefined}
        data-member="log-view"
      >
        {/* viewport */}
        <div
          class={styles.viewport}
          data-log-view-part="viewport"
          role="log"
          aria-label={props.label}
          aria-live="off"
          aria-busy={props.streaming ? true : undefined}
          tabindex={overflowing.value ? '0' : undefined}
          ref={viewport.attach}
        >
          {/* lines */}
          <ol class={styles.lines} role="list" ref={list.attach}>
            <Each of={props.lines} by={(line) => line.id} renew>
              {(line) => (
                <li class={styles.line} data-level={line.level}>
                  {/* marker */}
                  <span class={styles.marker} aria-hidden="true">
                    {line.level !== undefined ? <Icon name={line.level} size="sm" /> : null}
                  </span>
                  {line.level !== undefined ? (
                    <span class={styles.spoken}>{props.messages[line.level] + ' '}</span>
                  ) : null}
                  {line.time !== undefined ? (
                    <span class={styles.time}>{line.time + ' '}</span>
                  ) : null}
                  {/* text */}
                  <span class={styles.text}>
                    {line.source !== undefined ? (
                      <span class={styles.source}>{line.source + ' '}</span>
                    ) : null}
                    {/* message */}
                    <span>{line.text}</span>
                  </span>
                </li>
              )}
            </Each>
            {props.streaming ? (
              <li class={styles.end} aria-hidden="true">
                <span class={styles.caret} />
              </li>
            ) : null}
          </ol>
        </div>
        {/* jump */}
        <div class={styles.jump}>
          {/* backing */}
          <span class={styles.backing}>
            <Button
              variant="outline"
              tone="neutral"
              size="sm"
              icon="down"
              label={props.messages.jumpToLatest}
              onClick={() => jumpToEnd(viewport.value)}
            />
          </span>
        </div>
      </div>
    )
  })
}
